do $$
declare
  v_subject uuid; v_topic uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  select id into v_subject from public.subjects where code = 'est1-math';
  select id into v_topic from public.topics where subject_id = v_subject and name = 'Foundational Algebra';
  if exists (select 1 from public.exams where slug = 'foundational-algebra-practice-1') then
    raise exception 'Exam already exists';
  end if;
  values (v_subject, 'foundational-algebra-practice-1', 'Foundational Algebra — Practice 1',
    'Ten questions on linear equations, expressions, inequalities and linear models — a quick check of the algebra every EST I Math paper starts from.',
    'practice', v_topic, 'easy', 'free', 'draft', 15, 'ai_generated') returning id into v_exam;
  values (v_subject, null, '{"blocks": [{"type": "paragraph", "text": "If $3(x - 4) = 2x + 5$, what is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Expand: $3x - 12 = 2x + 5$. Subtract $2x$ from both sides and add $12$: $x = 17$."}]}'::jsonb, v_topic, 'application', 'easy', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, null, '{"blocks": [{"type": "paragraph", "text": "A line passes through the points $(0, 3)$ and $(2, 11)$. What is the slope of the line?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Slope $= \\dfrac{11 - 3}{2 - 0} = \\dfrac{8}{2} = 4$."}]}'::jsonb, v_topic, 'knowledge', 'easy', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following is equivalent to $5(2x - 3) - 4(x - 1)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Distribute: $10x - 15 - 4x + 4$. Combine like terms: $6x - 11$. Watch the sign: $-4 \\times -1 = +4$."}]}'::jsonb, v_topic, 'knowledge', 'easy', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, null, '{"blocks": [{"type": "paragraph", "text": "A gym charges a one-time joining fee of $\\$40$ plus $\\$25$ per month. Which equation gives the total cost $C$, in dollars, of a membership for $m$ months?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The monthly charge grows with $m$, so it multiplies $m$: $25m$. The joining fee is paid once, so it is added: $C = 25m + 40$."}]}'::jsonb, v_topic, 'application', 'easy', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, null, '{"blocks": [{"type": "paragraph", "text": "If $x + y = 10$ and $x - y = 4$, what is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add the two equations: $2x = 14$, so $x = 7$. (Then $y = 3$.)"}]}'::jsonb, v_topic, 'application', 'easy', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, null, '{"blocks": [{"type": "paragraph", "text": "What is the $x$-intercept of the line $3x - 4y = 24$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At the $x$-intercept, $y = 0$: $3x = 24$, so $x = 8$."}]}'::jsonb, v_topic, 'knowledge', 'easy', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, null, '{"blocks": [{"type": "paragraph", "text": "If $\\dfrac{2}{3}x + 5 = 11$, what is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract $5$: $\\dfrac{2}{3}x = 6$. Multiply by $\\dfrac{3}{2}$: $x = 9$."}]}'::jsonb, v_topic, 'application', 'easy', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following describes all values of $x$ that satisfy $4 - 2x > 10$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract $4$: $-2x > 6$. Dividing by a negative number reverses the inequality: $x < -3$."}]}'::jsonb, v_topic, 'application', 'medium', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, v_stim, '{"blocks": [{"type": "paragraph", "text": "What is the charge per kilometre?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Between 2 km and 5 km the fare rises by $\\$22 - \\$13 = \\$9$ over $3$ km, so the rate is $\\$9 \\div 3 = \\$3$ per km."}]}'::jsonb, v_topic, 'application', 'easy', 'ai_generated', 'draft') returning id into v_q;
  values (v_subject, v_stim, '{"blocks": [{"type": "paragraph", "text": "What is the fare for a 12-kilometre trip?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The fixed fee is $\\$13 - 2 \\times \\$3 = \\$7$, so the fare is $F = 7 + 3d$. For $d = 12$: $F = 7 + 36 = \\$43$."}]}'::jsonb, v_topic, 'application', 'medium', 'ai_generated', 'draft') returning id into v_q;
end $$;
